// Fission products, chapter 4 "TRISO layer migration and particle failure"
// (lessons 29-38): the small models behind the demos, shared by the pages,
// barrier-worker.js and check-fission.js (node). Pure functions, no DOM.
// Data: barrier-data.js and failure-data.js (generated by
// crates/dhoby-ghaut/examples/lesson_barriers from boon-lay's own calls).
//
// 1. latticeWalk: lesson 32's layered random walk. Atoms hop between radial
//    shells of the particle (kernel, buffer, IPyC, SiC, OPyC) at rates from
//    the real per-layer D: the finite-volume form of the diffusion equation
//    in a sphere, with the D at a face the harmonic mean of the two sides
//    (concentration continuous at interfaces, the K = 1 of boon-lay's
//    interface rule). Each hop takes an exponentially distributed time (a
//    kinetic Monte Carlo walk). The buffer is ONE shell: its D is so large
//    that it is well mixed, and splitting it would only add hops. It is a
//    teaching model; check-fission.js compares its medians with boon-lay's
//    own Walk-on-Spheres walker (barrier-data.js, "wos").
// 2. Ports of three one-line equations of boon-lay fuel failure, so the
//    sliders can move between the generator's grid points. Each is checked
//    against boon-lay's value in failure-data.js by check-fission.js:
//      thin-shell stress   sigma = r p FKOR / (2 d_o)   (PANAMA-I Eq (2))
//      Weibull failure     phi_1 = 1 - exp(-ln2 (sigma/sigma_o)^m)  (Eq (1))
//      combination         phi = 1 - (1-phi_o)(1-phi_1)(1-phi_2)   (p. -480-)
//    The equations are those of the PANAMA-I report (Verfondern & Nabielek,
//    HTA-IB-03/90), as boon-lay implements them.
(function () {
  "use strict";
  var root = typeof window !== "undefined" ? window : self;

  // A small seeded generator (mulberry32), for reproducible demos.
  function rng(seed) {
    var a = seed >>> 0;
    return function () {
      a = (a + 0x6D2B79F5) >>> 0;
      var t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // Log-linear interpolation of a D curve on grid tC at temperature t.
  function dAt(t, grid, d) {
    if (t <= grid[0]) return d[0];
    for (var i = 1; i < grid.length; i++) if (t <= grid[i]) {
      var u = (t - grid[i - 1]) / (grid[i] - grid[i - 1]);
      return Math.exp((1 - u) * Math.log(d[i - 1]) + u * Math.log(d[i]));
    }
    return d[d.length - 1];
  }

  // The shells: radii [5] (outer radius of each layer), D [5] for kernel,
  // buffer, IPyC, SiC, OPyC, and cells per layer [5]. Returns the cell edges,
  // the layer of each cell, and the hop rates in (to the centre) and out.
  function shells(radii, D, cells) {
    var edges = [0], layer = [], k, i;
    for (k = 0; k < 5; k++) {
      var r0 = k ? radii[k - 1] : 0, n = cells[k];
      for (i = 1; i <= n; i++) { edges.push(r0 + (radii[k] - r0) * i / n); layer.push(k); }
    }
    var nc = layer.length, vol = [], cen = [], rin = [], rout = [];
    for (i = 0; i < nc; i++) {
      var a = edges[i], b = edges[i + 1];
      vol.push((b * b * b - a * a * a) / 3);   // the 4 pi cancels with the face area
      cen.push(0.5 * (a + b));
    }
    for (i = 0; i < nc; i++) {
      var hi = edges[i + 1] - edges[i], Di = D[layer[i]];
      if (i + 1 < nc) {
        var hj = edges[i + 2] - edges[i + 1], Dj = D[layer[i + 1]];
        var cond = edges[i + 1] * edges[i + 1] / (hi / 2 / Di + hj / 2 / Dj); // face area / resistance
        rout.push(cond / vol[i]);
        rin[i + 1] = cond / vol[i + 1];
      } else {
        // The outer surface absorbs: half a cell of OPyC to it.
        rout.push(edges[nc] * edges[nc] * Di / (hi / 2) / vol[i]);
      }
    }
    rin[0] = 0;
    return { edges: edges, layer: layer, vol: vol, cen: cen, rin: rin, rout: rout, n: nc };
  }

  // One atom: born uniformly in the kernel's volume, walked until it leaves
  // the outer surface or maxHops is reached. Returns { t, hops, out, track }
  // with track = [[t, r], ...] sampled (every `every` hops, if asked).
  function walkAtom(S, kernelCells, r, maxHops, every) {
    var u = r(), cum = 0, tot = 0, i;
    for (i = 0; i < kernelCells; i++) tot += S.vol[i];
    var c = 0;
    for (i = 0; i < kernelCells; i++) { cum += S.vol[i] / tot; if (u <= cum) { c = i; break; } }
    var t = 0, hops = 0, track = every ? [[0, S.cen[c]]] : null;
    while (hops < maxHops) {
      var a = S.rin[c], b = S.rout[c], w = a + b;
      t += -Math.log(1 - r()) / w;
      hops++;
      if (r() * w < b) c++; else c--;
      if (c >= S.n) { if (track) track.push([t, S.edges[S.n]]); return { t: t, hops: hops, out: true, track: track }; }
      if (track && hops % every === 0) track.push([t, S.cen[c]]);
    }
    return { t: t, hops: hops, out: false, track: track };
  }

  var CELLS = [10, 1, 4, 4, 4];
  function latticeWalk(radii, D, n, seed, maxHops) {
    var S = shells(radii, D, CELLS), r = rng(seed), times = [], capped = 0, hops = 0;
    for (var i = 0; i < n; i++) {
      var w = walkAtom(S, CELLS[0], r, maxHops, 0);
      hops += w.hops;
      if (w.out) times.push(w.t); else capped++;
    }
    return { times: times, capped: capped, hops: hops };
  }
  // The median of n walks, counting capped (unreleased) ones as later than
  // all released; null if fewer than half released.
  function median(times, n) {
    if (times.length * 2 < n) return null;
    var t = times.slice().sort(function (a, b) { return a - b; });
    return t[Math.floor((n - 1) / 2)];
  }

  // The exact mean exit time [s] for atoms born evenly in the kernel, from
  // the continuum diffusion equation with continuous concentration and flux
  // at every interface: D(r) T'(r) = -r/3, so
  //   <T> = a^2/(15 D_kernel) + sum over shells (r_out^2 - r_in^2)/(6 D_i).
  // The same formula as walk.rs exact_mean_exit in the generator, which
  // check-fission.js compares this with; the lattice walk is checked against it.
  function exactMean(radii, D) {
    var t = radii[0] * radii[0] / (15 * D[0]);
    for (var k = 1; k < 5; k++) t += (radii[k] * radii[k] - radii[k - 1] * radii[k - 1]) / (6 * D[k]);
    return t;
  }
  function mean(times) { var s = 0; times.forEach(function (t) { s += t; }); return s / times.length; }

  // Lesson 33: thin-shell SiC stress (Eq (2)).
  function stress(p, rMean, d0, fkor) { return rMean * p * Math.max(fkor, 1) / (2 * d0); }
  // Lesson 34: Weibull with the median as scale (Eq (1)).
  function weibull(s, s0, m) {
    if (s0 <= 0) return 1;
    if (s <= 0) return 0;
    return 1 - Math.exp(-Math.LN2 * Math.pow(s / s0, m));
  }
  // Lessons 36-37: survival multiplies.
  function total(phiO, phi1, phi2) { return 1 - (1 - phiO) * (1 - phi1) * (1 - phi2); }

  root.BarrierPhysics = {
    rng: rng, dAt: dAt, exactMean: exactMean, mean: mean, shells: shells, walkAtom: walkAtom, latticeWalk: latticeWalk, median: median,
    CELLS: CELLS, stress: stress, weibull: weibull, total: total
  };
})();
